<template><span class="avatar" :class="member?.color||'avatar-k'" :style="suggestedStyle"><img v-if="photo" :src="photo" :alt="member?.name"/><span v-else-if="!suggestedStyle">{{member?.initials||'?'}}</span></span></template>
<script setup lang="ts">import{computed}from"vue";import type{CSSProperties}from"vue";import type{Member}from"../stores/taskflow";const props=defineProps<{member?:Member}>();const photo=computed(()=>{const a=props.member?.avatar;return a&&!a.startsWith("suggested:")?a:undefined}),suggestedStyle=computed<CSSProperties|undefined>(()=>{const a=props.member?.avatar;if(!a?.startsWith("suggested:"))return;const n=Number(a.split(":")[1])||0;return{backgroundImage:"url(/avatar-suggestions.png)",backgroundSize:"300% 200%",backgroundPosition:`${n%3*50}% ${Math.floor(n/3)*100}%`}});</script>
